(()=>{'use strict';const $=id=>document.getElementById(id),mod=(x,n)=>(x%n+n)%n,reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches,rotor=$('wheelRotor'),button=$('spinDiscovery'),groupFor=id=>GALLERY_GROUPS.find(g=>g.ids.includes(id));let angle=0,animation=null,epoch=0,spins=0,spinning=false,resultId=null;
const sectorAngle=360/GALLERY_PROJECTS.length;
const names={'text-mining':'Text Mining','road-safety':'Road Safety',eeg:'EEG Signals','home-affordability':'Mortgage',oil:'Oil Research','hotel-security':'Hotel Security','movie-night':'Movie Night',cryptography:'Cryptography','digital-forensics':'Forensics','websocket-security':'WebSocket','nfe-security':'NFE Security'};
function svg(name,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',name);for(const [key,val]of Object.entries(attrs))el.setAttribute(key,val);return el}const xy=(r,deg)=>[280+r*Math.cos(deg*Math.PI/180),280+r*Math.sin(deg*Math.PI/180)];
rotor.append(svg('circle',{cx:280,cy:280,r:252,fill:'#091a2c',stroke:'#87bdc344','stroke-width':2}));for(const [i,p]of GALLERY_PROJECTS.entries()){const group=groupFor(p.id),mid=-90+i*sectorAngle,a=xy(240,mid-sectorAngle/2),b=xy(240,mid+sectorAngle/2),sector=svg('g',{'data-wheel-project':p.id});sector.append(svg('path',{d:`M280 280 L${a[0]} ${a[1]} A240 240 0 0 1 ${b[0]} ${b[1]} Z`,fill:group.color,'fill-opacity':.13,stroke:group.color,'stroke-opacity':.36,'stroke-width':1.2,class:'wheel-sector'}));const at=xy(166,mid),text=svg('text',{x:at[0],y:at[1],'text-anchor':'middle','dominant-baseline':'middle',transform:`rotate(${mid+90} ${at[0]} ${at[1]})`,fill:group.color,class:'wheel-project-label'});text.textContent=names[p.id]||p.short||p.title;sector.append(text);const dot=xy(226,mid);sector.append(svg('circle',{cx:dot[0],cy:dot[1],r:3,fill:group.color,'fill-opacity':.8}));rotor.append(sector)}rotor.append(svg('circle',{cx:280,cy:280,r:77,fill:'#0b1f30',stroke:'#a4e4d24d','stroke-width':1.4}));
function sampleIndex(){const n=GALLERY_PROJECTS.length,limit=Math.floor(4294967296/n)*n,value=new Uint32Array(1);do{crypto.getRandomValues(value)}while(value[0]>=limit);return value[0]%n}
function reveal(id,random=true){const p=GALLERY_PROJECTS.find(p=>p.id===id),g=groupFor(id);resultId=id;$('discoveryResult').style.setProperty('--discovery-accent',g.color);$('discoveryResult').classList.add('has-result');$('discoveryResult').classList.remove('is-spinning');$('discoveryCover').dataset.id=id;$('discoveryCoverTitle').innerHTML=p.cover;$('discoveryGroup').textContent=g.title;$('discoveryGroup').style.color=g.color;$('discoveryTitle').textContent=p.title;$('discoverySummary').textContent=p.summary;$('discoverySkills').replaceChildren(...p.skills.map(s=>{const li=document.createElement('li');li.textContent=s;return li}));const a=$('discoveryExplore');a.href=p.href;a.dataset.galleryReady='true';a.hidden=false;$('discoveryLabel').textContent=random?'YOUR RANDOM DISCOVERY':'SELECTED FROM COLLECTION';$('discoveryCounter').textContent=spins?'SPINS / '+String(spins).padStart(2,'0'):'';$('discoveryHint').textContent='Explore plays this project’s original opening animation. Or spin again.';for(const e of rotor.querySelectorAll('[data-wheel-project]'))e.classList.toggle('wheel-selected',e.dataset.wheelProject===id);$('discoveryAnnouncement').textContent=(random?'Discovered: ':'Selected: ')+p.title+'. Choose Explore project to open.'}
function cancel(){epoch++;animation?.cancel();animation=null;spinning=false;button.disabled=false;button.innerHTML=(resultId?'Spin again':'Spin to discover')+' <span aria-hidden="true">↻</span>';rotor.style.transform=`rotate(${angle}deg)`;$('discoveryResult').classList.remove('is-spinning');$('discoveryResult').setAttribute('aria-busy','false');if(resultId)$('discoveryExplore').hidden=false;$('discoveryHint').textContent=resultId?'Explore plays this project’s original opening animation. Or spin again.':'The result stays here until you decide to open it.'}
async function spin(){if(spinning)return;const mine=++epoch,index=sampleIndex(),p=GALLERY_PROJECTS[index],target=angle+1800+mod(-index*sectorAngle-angle,360);spinning=true;button.disabled=true;button.textContent='Discovering…';$('discoveryResult').classList.add('is-spinning');$('discoveryResult').setAttribute('aria-busy','true');$('discoveryExplore').hidden=true;$('discoveryHint').textContent='The wheel is turning. Your next project will appear here.';$('discoveryAnnouncement').textContent='Selecting a project.';if(!reduced()){animation=rotor.animate([{transform:`rotate(${angle}deg)`},{transform:`rotate(${target}deg)`}],{duration:3600,easing:'cubic-bezier(.12,.78,.12,1)',fill:'forwards'});try{await animation.finished}catch{return}}if(epoch!==mine)return;angle=mod(target,360);animation?.cancel();animation=null;rotor.style.transform=`rotate(${angle}deg)`;spinning=false;spins++;button.disabled=false;button.innerHTML='Spin again <span aria-hidden="true">↻</span>';$('discoveryResult').setAttribute('aria-busy','false');reveal(p.id);window.galleryControls.select(p.id,{origin:'random'})}
button.onclick=spin;addEventListener('gallery-mode',e=>{if(e.detail!=='random')cancel()});addEventListener('gallery-selection',e=>{if(e.detail.origin==='random'||!window.galleryControls.isRandom())return;cancel();const p=GALLERY_PROJECTS.find(p=>p.id===e.detail.id);angle=mod(-GALLERY_PROJECTS.indexOf(p)*sectorAngle,360);rotor.style.transform=`rotate(${angle}deg)`;reveal(p.id,false)});document.addEventListener('visibilitychange',()=>{if(document.hidden&&spinning)cancel()});matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{if(spinning)cancel()});
})();
